def chunk(text: str, size: int = {{chunk_size}}, overlap: int = {{overlap}}) -> list[str]:
    chunks, start = [], 0
    while start < len(text):
        end = min(start + size, len(text))
        chunks.append(text[start:end])
        if end == len(text):
            break
        start = end - overlap
    return chunks

if __name__ == "__main__":
    print(chunk("a" * 2500))
